# C1 bank growth: C2 grammar (+78). Kid/teen topics (the Starlight Library, apprentices, dragons, space, inventions); rule + example and a "why not" note for every wrong option.
from c1_grow import m
C2G = [
 # inversion & fronting
 m("Nowhere ___ a stranger collection of maps than in the Starlight Library.", "will you find", ["you will find", "you find", "found you"], "Nowhere at the start → auxiliary + subject. Example: Nowhere else can you see such stars.", ["After nowhere at the start we invert.", "Present simple would need do: do you find.", "Found you puts the main verb first, which isn't inversion."]),
 m("Only if the apprentice reads the rune aloud ___.", "will the door open", ["the door will open", "the door opens", "opens the door"], "Only if + clause first → inversion in the main clause. Example: Only if you ask will he help.", ["After only if, the main clause is inverted.", "We need inversion: will the door open.", "The main verb can't come before the subject here."]),
 m("Not until the final chapter ___ who had stolen the moonstone.", "is it revealed", ["it is revealed", "it reveals", "reveals it"], "Not until + phrase first → inversion in the main clause. Example: Not until midnight did they stop.", ["After not until we invert: is it.", "It reveals would be active; the secret is revealed.", "The main verb can't come first."]),
 m("In no way ___ responsible for the dragon's bad temper.", "are we", ["we are", "we're not", "aren't we"], "In no way (= not at all) + inversion. Example: In no way is this fair.", ["After in no way we invert.", "In no way is already negative, so no not.", "Aren't adds a second negative."]),
 m("Gone ___ the days when every book was copied by hand.", "are", ["have", "were being", "did"], "Fronted adjective/participle + be + subject (literary). Example: Gone are the days of dial-up internet.", ["Have gone would need a participle after have, and the word order differs.", "Were being isn't used in this fixed pattern.", "Did can't go with gone."]),
 m("Into the cave ___, holding a single lantern.", "crept the apprentice", ["creeping the apprentice", "did creep the apprentice", "crept did the apprentice"], "Fronted place phrase + verb + noun subject (literary). Example: Down came the rain.", ["Creeping is not a full verb, so the sentence has no main verb.", "Did is not used with this kind of inversion.", "Crept did isn't English."]),
 m("Here ___ the moment we've all been waiting for!", "comes", ["come", "is coming it", "it comes"], "Here/There + verb + noun subject. Example: Here comes the bus!", ["The subject is singular: the moment comes.", "Is coming it adds an extra pronoun.", "It comes would need 'Here it comes', with a pronoun only."]),
 m("Strange ___ may seem, the oldest book in the library is blank.", "as it", ["although it", "though if", "as if it"], "Adjective + as/though + subject + verb = although it is… Example: Tired as she was, she kept going.", ["Although can't follow the adjective like this.", "Though if isn't English.", "As if means 'in a way that suggests'."]),
 m("Try ___ they might, the robots could not climb the spiral stairs.", "as", ["though", "so", "if"], "Try as + subject + might = however hard they tried. Example: Try as I might, I couldn't sleep.", ["Though isn't used in this fixed phrase.", "So isn't used in this fixed phrase.", "If isn't used in this fixed phrase."]),
 m("___ he to reveal the secret, the whole guild would turn against him.", "Were", ["Was", "Should", "Had"], "Were + subject + to-infinitive = If he were to (formal). Example: Were she to resign, we'd be lost.", ["Was isn't used in formal inversion.", "Should + subject is followed by the base form, not to.", "Had + subject needs a past participle."]),
 m("___ it not been for the owl's warning, the scrolls would have burned.", "Had", ["Were", "If", "Should"], "Had it not been for = without (past). Example: Had it not been for you, I'd have failed.", ["Were it not for is present: Were it not for you, I'd fail.", "If would need had: If it had not been for.", "Should it not been isn't a form."]),
 m("Such ___ the dragon's hunger that it ate the entire feast.", "was", ["had", "did", "made"], "Such + be + noun + that (emphatic). Example: Such was his talent that…", ["Had doesn't fit this pattern.", "Did doesn't fit this pattern.", "Made doesn't fit this pattern."]),
 # subjunctive / formulaic
 m("___ it a comet or a satellite, it was the brightest thing in the sky.", "Be", ["Being", "Was", "Were it"], "Be it X or Y = whether it is X or Y (formal subjunctive). Example: Be it rain or shine, we'll play.", ["Being doesn't introduce this formula.", "Was would need whether.", "Were it repeats it."]),
 m("Far ___ it from me to criticise, but your spell is upside down.", "be", ["is", "being", "was"], "Far be it from me to… = I don't want to…, but (fixed subjunctive). Example: Far be it from me to complain.", ["Is isn't used in this fixed phrase.", "Being isn't used in this fixed phrase.", "Was isn't used in this fixed phrase."]),
 m("Long ___ the queen of the fairy kingdom!", "live", ["lives", "living", "lived"], "Subjunctive wish formula: Long live… Example: Long live the king!", ["No -s in the subjunctive.", "Living isn't the formula.", "Lived is past."]),
 m("If need ___, we'll sleep in the library overnight.", "be", ["is", "been", "being"], "If need be = if necessary (fixed subjunctive). Example: I'll go alone if need be.", ["Is isn't used in this fixed phrase.", "Been isn't used here.", "Being isn't used here."]),
 m("The council of owls demanded that the thief ___ the stolen feather at once.", "return", ["returns", "returned", "would return"], "Mandative subjunctive: demand/insist that + base verb. Example: They insisted he leave.", ["No -s in the subjunctive.", "Returned is past.", "Would return isn't the subjunctive form."]),
 m("Would that I ___ able to read ancient Draconic!", "were", ["am", "would be", "be"], "Would that + past (were) = I wish (literary). Example: Would that it were true!", ["Am is present indicative.", "Would be doesn't follow would that.", "Be is the mandative subjunctive, not used here."]),
 m("She spoke quietly lest the sleeping giant ___.", "wake", ["wakes", "would wake up to", "to wake"], "Lest + (should) + base verb = so that … not. Example: He hid lest he be seen.", ["No -s after lest in the subjunctive.", "Would wake up to adds extra words that don't fit.", "No to after lest."]),
 m("It's not as if the robot ___ us; it simply didn't hear.", "had ignored", ["has ignored", "ignores", "would ignore"], "It's not as if + past/past perfect = an unreal comparison. Example: It's not as if I had a choice.", ["Has ignored is real present perfect.", "Ignores is a real present fact.", "Would ignore doesn't follow as if here."]),
 m("Suffice it ___ that the experiment did not go to plan.", "to say", ["saying", "said", "say"], "Suffice it to say = I'll just say (fixed phrase). Example: Suffice it to say, we were late.", ["Saying isn't used here.", "Said isn't used here.", "We need to."]),
 # ellipsis and substitution
 m("'Will the dragon come back?' 'I hope ___.'", "so", ["it", "that", "yes"], "So replaces a whole clause after hope, think, expect. Example: 'Is it ready?' 'I think so.'", ["It doesn't replace a clause here.", "That doesn't follow hope in short answers.", "Yes isn't used after hope."]),
 m("'Is the library closed today?' 'I'm afraid ___.'", "so", ["yes", "it", "that"], "I'm afraid so / not = a polite yes/no. Example: 'Is it raining?' 'I'm afraid so.'", ["Yes isn't used after I'm afraid.", "It isn't used in this short answer.", "That isn't used here."]),
 m("Mira can juggle five balls, and ___ her twin brother.", "so can", ["so does", "neither can", "can so"], "So + auxiliary + subject = too (matching the auxiliary). Example: I can swim and so can she.", ["The first verb uses can, so the auxiliary is can, not does.", "Neither is for negatives.", "Can so isn't the right order."]),
 m("The apprentice didn't notice the trapdoor, and ___.", "nor did the wizard", ["the wizard didn't too", "so did the wizard", "neither the wizard did"], "Nor/Neither + auxiliary + subject after a negative. Example: I didn't go, nor did she.", ["Too isn't used with negatives: we say either.", "So is for positive statements.", "After neither we invert: neither did the wizard."]),
 m("You may borrow the telescope if you'd like ___.", "to", ["it", "so", "that"], "Ellipsis: keep to after like, want, need. Example: Come with us if you want to.", ["It isn't needed after like here.", "So isn't used after like.", "That doesn't fit."]),
 # complex clauses and comparison
 m("The spell wasn't so much difficult ___ long.", "as", ["than", "but", "like"], "Not so much X as Y = it's more Y than X. Example: He's not so much shy as cautious.", ["Than doesn't follow so much in this pattern.", "But doesn't fit this pattern.", "Like isn't used here."]),
 m("He didn't ___ say goodbye before he flew off on his broomstick.", "so much as", ["as much as", "so many as", "even as"], "Not so much as = not even. Example: She didn't so much as look at me.", ["As much as would mean equally.", "So many as isn't English.", "Even as means while."]),
 m("The baby dragon can't fly, ___ breathe fire.", "let alone", ["not to say", "rather than", "never mind to"], "Let alone = and certainly not (after a negative). Example: I can't walk, let alone run.", ["Not to say means 'or even'.", "Rather than shows preference.", "Never mind is used without to."]),
 m("For ___ his cleverness, the inventor couldn't tie his own shoelaces.", "all", ["every", "whole", "much"], "For all + noun = despite. Example: For all its faults, I love this city.", ["Every doesn't fit this fixed phrase.", "Whole needs the: the whole.", "Much isn't used here."]),
 m("What ___ the storm and the power cut, we never finished the film.", "with", ["about", "for", "by"], "What with + nouns = because of (several things). Example: What with work and school, I'm exhausted.", ["What about is a suggestion.", "What for asks why.", "What by isn't a phrase."]),
 m("The older the scroll, ___ it is to read.", "the harder", ["harder", "the hardest", "more hard"], "The + comparative …, the + comparative. Example: The higher you climb, the colder it gets.", ["We need the before harder.", "Hardest is superlative.", "Hard takes -er, and we need the."]),
 m("She is no ___ a magician than I am a mermaid!", "more", ["less", "better", "rather"], "No more X than Y = just as untrue as. Example: He's no more a doctor than I am.", ["No less means equally true, the opposite.", "No better compares quality.", "No rather isn't English."]),
 m("The map was every ___ as old as the legend claimed.", "bit", ["piece", "way", "much"], "Every bit as + adjective = just as. Example: She's every bit as clever as her sister.", ["Every piece isn't the phrase.", "Every way isn't used before as.", "Every much isn't English."]),
 m("The professor, ___ is often the case, forgot his glasses.", "as", ["which", "like", "what"], "As is often the case = as usual (as refers to the whole clause). Example: As is often the case, he was late.", ["Which needs a noun or clause before it, not after the comma here.", "Like isn't used in this fixed phrase.", "What can't start this clause."]),
 m("She explained, ___ it were, how to fold a star from moonlight.", "as", ["so", "though", "like"], "As it were = in a way, so to speak. Example: He's the heart, as it were, of the team.", ["So it were isn't English.", "Though it were isn't the fixed phrase.", "Like it were isn't the fixed phrase."]),
 # tense/aspect subtleties
 m("By the time the eclipse ends, the astronomers ___ for twelve hours straight.", "will have been observing", ["will observe", "will be observing", "have been observing"], "Future perfect continuous: duration up to a future point. Example: By noon, we'll have been walking for six hours.", ["Will observe doesn't show duration up to then.", "Will be observing is in progress, without the duration up to that point.", "Have been observing ends now, not at a future point."]),
 m("I ___ you'd lend me your spellbook for the weekend.", "was hoping", ["hope to", "have hoped", "had hope"], "Past continuous for a tentative, polite request. Example: I was wondering if you could help.", ["Hope to needs a verb: hope to borrow.", "Have hoped sounds as if the hope has ended.", "Had hope isn't a verb form."]),
 m("The castle was ___ to be demolished when the dragon moved in.", "about", ["due for", "close", "near"], "Be about to + verb = very soon (here in the past). Example: I was about to call you.", ["Due for is followed by a noun.", "Close is followed by to + noun or -ing, not an infinitive.", "Near isn't followed by to-infinitive."]),
 m("No one ___ the professor's warning until the stairs began to vanish.", "had heeded", ["has heeded", "heeds", "was heeded"], "Past perfect for an earlier action before a past event. Example: Nobody had noticed until it was too late.", ["Has heeded is present perfect.", "Heeds is present.", "Was heeded is passive and needs a different subject."]),
 m("The apprentice ___ have been practising; her spells are flawless.", "must", ["can't", "needn't", "should"], "Must have been + -ing = a confident deduction about a past activity. Example: You must have been waiting ages.", ["Can't have means you're sure it didn't happen.", "Needn't have means it wasn't necessary.", "Should have means it was expected but didn't happen."]),
 m("Had I but known the stairs moved, I ___ them.", "would have avoided", ["would avoid", "had avoided", "avoided"], "Had I but known = if only I had known (literary third conditional). Example: Had I but known, I'd have stayed.", ["Would avoid is present/future.", "Had avoided belongs in the if-clause.", "Avoided is a real past fact."]),
 # nominal / adjectival patterns
 m("The likelihood of the comet ___ Earth is extremely small.", "hitting", ["to hit", "hits", "will hit"], "Noun + of + subject + -ing. Example: the chance of it raining.", ["After of we use -ing.", "Hits needs a subject and that.", "Will hit needs that: that it will hit."]),
 m("Her ___ to share the prize won everyone's respect.", "willingness", ["willing", "will", "willingly"], "Adjective → noun with -ness. Example: kind → kindness.", ["Willing is an adjective.", "Will is a different noun (determination).", "Willingly is an adverb."]),
 m("It was ___ of you to save me a seat!", "thoughtful", ["thought", "thoughtfully", "thinking"], "It's + adjective + of + person + to = describing behaviour. Example: It was kind of you to help.", ["Thought is a noun or past verb.", "Thoughtfully is an adverb.", "Thinking is a verb form."]),
 m("The dragon is ___ to wake before spring.", "unlikely", ["improbable", "impossible to", "doubtful"], "Be (un)likely + to-infinitive. Example: She's likely to win.", ["Improbable isn't used with to-infinitive like this.", "Impossible to repeats to.", "Doubtful is followed by that or whether."]),
 m("Brave ___ she was, the apprentice trembled before the sphinx.", "though", ["despite", "however", "even"], "Adjective + though + subject + be = although she was brave. Example: Small though it is, it's powerful.", ["Despite needs a noun.", "However would need to come first: however brave.", "Even needs though or if."]),
 m("___ brave the knight, he would not face the sphinx's riddles alone.", "However", ["Whatever", "Whichever", "Although"], "However + adjective (+ be omitted) = no matter how. Example: However hard the test, we'll pass.", ["Whatever is for things.", "Whichever is a choice between options.", "Although needs a full clause."]),
 m("___ opens the box will be granted one wish.", "Whoever", ["Whatever", "Anyone", "Who"], "Whoever = any person who. Example: Whoever finishes first wins.", ["Whatever is for things.", "Anyone would need who: anyone who opens.", "Who alone can't be the subject like this in modern English."]),
 m("Take ___ path you like; they all lead to the castle.", "whichever", ["whoever", "however", "whenever"], "Whichever + noun = any one of a group. Example: Choose whichever colour you like.", ["Whoever is for people.", "However is for manner or degree.", "Whenever is for time."]),
 # determiners / quantity
 m("Not a ___ star could be seen through the thick clouds.", "single", ["one only", "lonely", "sole of"], "Not a single + noun = none at all (emphatic). Example: Not a single person came.", ["One only isn't natural English.", "Lonely is about feelings.", "Sole of isn't English."]),
 m("___ the apprentices passed the test; even the youngest.", "All of", ["Every of", "Each", "Whole"], "All of + the + plural noun. Example: All of the books are new.", ["Every can't be followed by of.", "Each needs of the: each of the apprentices.", "Whole needs the before it and a singular noun."]),
 m("There's ___ little hope of finding the lost spellbook.", "precious", ["pretty much", "valuable", "rare"], "Precious little/few = very little. Example: There's precious little time.", ["Pretty much little isn't English.", "Valuable doesn't go before little.", "Rare doesn't go before little."]),
 m("The two moons are ___ the same size.", "much", ["many", "very", "lot"], "Much the same = almost the same. Example: The towns are much the same.", ["Many isn't used here.", "Very the same isn't English.", "Lot isn't used here."]),
 # verb patterns at C2
 m("The wizard would rather the apprentices ___ the potions unsupervised.", "didn't mix", ["don't mix", "not mix", "not to mix"], "Would rather + person + past simple. Example: I'd rather you didn't smoke.", ["Present tense doesn't follow would rather + person.", "We need did: didn't mix.", "No to here."]),
 m("She was overheard ___ that the treasure was buried under the oak.", "to say", ["say", "saying that", "said"], "Passive of hear/see + to-infinitive (or -ing). Example: He was heard to shout.", ["The passive needs to.", "Saying that repeats that.", "Said is past."]),
 m("I resent ___ called a 'little helper' by the older students.", "being", ["to be", "be", "been"], "Resent + -ing (passive: being + p.p.). Example: I resent being ignored.", ["Resent isn't followed by to-infinitive.", "We need -ing.", "Been needs have."]),
 m("The inventor is reputed ___ over a hundred gadgets.", "to have designed", ["having designed", "to design", "designed"], "Be reputed/said to have + p.p. = it is said that he did. Example: She is reputed to have met the king.", ["Reputed is followed by to-infinitive.", "To design is about now or general habits.", "Designed alone doesn't follow is reputed."]),
 m("We were left ___ how the magician had escaped.", "wondering", ["to wonder at", "wondered", "wonder"], "Be left + -ing = continue to feel or do. Example: We were left speechless / wondering.", ["To wonder at means to admire.", "Wondered is past.", "Wonder needs -ing here."]),
 m("There's no ___ what the dragon might do next.", "telling", ["tell", "to tell of", "told"], "There's no + -ing = it's impossible to. Example: There's no knowing how long it'll take.", ["We need -ing.", "To tell of isn't the pattern.", "Told is past."]),
 m("It was the potion, ___ than the spell, that turned him into a frog.", "rather", ["more", "instead", "other"], "X rather than Y = X and not Y. Example: It was luck rather than skill.", ["More than would say it was more of the potion than the spell.", "Instead needs of.", "Other than means except."]),
 m("No sooner ___ than the lights went out.", "had the wizard spoken", ["the wizard had spoken", "did the wizard speak", "spoke the wizard"], "No sooner + had + subject + p.p. + than. Example: No sooner had we sat down than it rained.", ["After no sooner we invert.", "Did with no sooner is rare; the pattern uses had.", "Spoke the wizard isn't the pattern."]),
 m("The scroll, the ink ___ had faded, was almost unreadable.", "of which", ["whose of", "which", "that"], "Noun + of which (formal possessive for things). Example: a house, the roof of which leaks.", ["Whose of isn't English.", "Which alone doesn't show possession here.", "That can't follow a comma."]),
 m("There were two doors, ___ led to the dragon's lair.", "neither of which", ["neither of them", "none of which", "both which"], "Quantifier + of which in non-defining clauses. Example: two answers, neither of which was right.", ["Neither of them would make a run-on sentence.", "None is for more than two.", "Both which is missing of."]),
 m("The apprentice, ___ talent nobody had noticed, solved the riddle first.", "whose", ["who's", "of whom", "that her"], "Whose = of whom/which (possession). Example: the girl whose bag was lost.", ["Who's = who is.", "Of whom would need different word order: the talent of whom.", "That her isn't grammatical."]),
 m("It is high time the library ___ its ancient lift.", "replaced", ["replaces", "replace", "had replaced"], "It's high time + past simple = it should happen now. Example: It's high time we left.", ["Present simple doesn't follow it's high time + subject.", "The base form isn't used here.", "Past perfect isn't used after it's high time."]),
 m("I'd as soon ___ in the library as go to the party.", "stay", ["staying", "to stay", "stayed"], "Would as soon + base verb = would equally prefer. Example: I'd as soon walk.", ["No -ing after would as soon.", "No to after would as soon.", "Stayed is past."]),
 m("Given ___ chance, the parrot would recite the entire alphabet.", "half a", ["a half", "half of", "the half"], "Given half a chance = if they had even a small opportunity. Example: Given half a chance, he'd sleep all day.", ["A half chance isn't the fixed phrase.", "Half of chance isn't English.", "The half chance isn't the fixed phrase."]),
 m("Little ___ the apprentice care that her robes were muddy.", "did", ["was", "had", "has"], "Little + did + subject + base verb = not at all. Example: Little did he care.", ["Was would need caring.", "Had would need cared.", "Has would need cared and is present."]),
 m("Only by working together ___ the giant puzzle.", "could they solve", ["they could solve", "they solved", "solved they"], "Only by + -ing first → inversion. Example: Only by practising can you improve.", ["After only by we invert.", "Past simple would need did they solve.", "The main verb can't come before the subject here."]),
 m("So ___ was the music that even the stone statues seemed to listen.", "enchanting", ["enchanted", "enchantment", "enchant"], "So + adjective + be + subject (inversion). The -ing adjective describes the cause. Example: So boring was the talk that…", ["Enchanted describes how someone felt, not the music.", "Enchantment is a noun.", "Enchant is a verb."]),
 m("The spell must be performed exactly as written, ___ it will backfire.", "otherwise", ["unless", "whereas", "lest"], "Otherwise = if not (after a clause). Example: Hurry, otherwise we'll be late.", ["Unless would need a different clause: unless it is performed…", "Whereas shows contrast.", "Lest means 'so that … not', which doesn't fit 'it will backfire'."]),
 m("___ the dragon spoke, the room fell silent.", "The moment", ["During", "Meanwhile", "By the time that"], "The moment/minute (that) = as soon as. Example: The moment I saw her, I knew.", ["During needs a noun.", "Meanwhile is an adverb, not a conjunction.", "By the time that suggests something finished earlier."]),
 m("I'd have helped you, ___ you asked me.", "had", ["did", "if", "should"], "Inverted third conditional in the second clause: had + subject + p.p. Example: I'd have come, had I known.", ["Did you ask isn't a conditional form.", "If would need had: if you had asked.", "Should is for future possibilities."]),
 m("Not that it ___, but the dragon prefers its tea with honey.", "matters", ["matter", "mattered of", "is mattering"], "Not that + clause = I'm not saying it's important. Example: Not that I care, but…", ["The subject it needs -s.", "Mattered of isn't English.", "Matter isn't used in the continuous here."]),
]
